    ids = [opt['id'] for opt in combo]
    owners = [opt['owner'] for opt in combo]
    qualities = [opt['quality'] for opt in combo]
    costs = [opt['cost'] for opt in combo]
    tags_all = []
    for opt in combo:
        tags_all += opt['tags']
    # Check unique owners
    unique_owners = True
    for i in range(len(owners)):
        for j in range(i+1, len(owners)):
            if owners[i] == owners[j]:
                unique_owners = False
    if not unique_owners:
        continue
    # Check cover tags
    cover_tags = goal['cover'].get('tags', [])
    cover_ok = True
    for tag in cover_tags:
        if tag not in tags_all:
            cover_ok = False
    if not cover_ok:
        continue
    # Check sum bounds
    quality_sum = sum(qualities)
    cost_sum = sum(costs)
    if quality_sum < goal['sum_bounds']['quality']['min']:
        continue
    if cost_sum > goal['sum_bounds']['cost']['max']:
        continue
    # Check count
    if len(ids) < goal['min_count'] or len(ids) > goal['max_count']:
        continue
    # no_conflicts is false, so conflicts allowed
    # closed_dependencies is false, so no check
    # Check valid
    if valid(ids):
        result = ids
        break
